#!/usr/bin/env python3
# Blackout-Radar Schritt 1: Stufen 1-3, eigene Pings, Kachel. Kein Push, kein Mesh.
# Basis: Stand nach apply-usv-entwarnung (PR 23), Marker _PSH_ARM. Kein pip, kein apt.
from __future__ import annotations
import base64, hashlib, json, os, shutil, sys
from datetime import datetime
from pathlib import Path

DASH = Path("/home/fmg/prepper-dashboard")
PATCH = ("dashboard.py", "lage_pages.py")
NEU = ("blackout_radar.py", "blackout_radar_targets.json")
BASIS = {
    "dashboard.py": ("7d72f86e85b1c0f062feedf756a7e0d56b62e129dd332e53a4fc8e8d3e4d827c", 1384714),
    "lage_pages.py": ("7f75c1a511872c63ac86771d393e019a8f3cba36e1a1ae7bcfca48a2caceec77", 217209),
}
MARKER = b"_PSH_ARM"
ZIEL = b"blackoutRadar1"

def load():
    raw = PAYLOAD if isinstance(PAYLOAD, dict) else json.loads(PAYLOAD)
    paare = {name: [(base64.b64decode(x["old"]), base64.b64decode(x["new"])) for x in raw["pairs"][name]] for name in PATCH}
    neu = {name: base64.b64decode(raw["neu"][name]) for name in NEU}
    return paare, neu

def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

def basis_ok(name, data: bytes) -> bool:
    soll, laenge = BASIS[name]
    if sha(data) != soll or len(data) != laenge:
        return False
    if name == "dashboard.py":
        return MARKER in data and ZIEL not in data
    if name == "lage_pages.py":
        return b'id="borCard"' not in data and b"Uplink-Handover" not in data
    return False

def fenster(now=None):
    from zoneinfo import ZoneInfo
    jetzt = now or datetime.now(ZoneInfo("Europe/Berlin"))
    m = jetzt.minute
    return (not (m >= 45 or m <= 4)), "Berlin Minute %02d" % m

def schreiben(path: Path, data: bytes):
    mode = path.stat().st_mode & 0o777 if path.exists() else 0o644
    tmp = path.with_name("." + path.name + ".tmp-bor")
    if tmp.exists():
        raise RuntimeError("temporaere Datei existiert")
    try:
        with open(tmp, "wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(tmp, mode)
        os.replace(tmp, path)
    finally:
        if tmp.exists():
            try:
                tmp.unlink()
            except OSError:
                pass

def sichern(path: Path, data: bytes):
    stempel = datetime.now().astimezone().strftime("%Y%m%dT%H%M%S")
    alt = sorted(path.parent.glob(path.name + ".bak-bor-*"))
    bak = path.with_name(path.name + ".bak-bor-" + stempel)
    shutil.copy2(path, bak)
    if bak.read_bytes() != data:
        bak.unlink()
        raise RuntimeError("Sicherung weicht ab")
    for alt_pfad in alt[:-2]:
        try:
            alt_pfad.unlink()
        except OSError:
            pass

def verwandle(data, pairs):
    if all(data.count(neu) == 1 and data.count(old) == 0 for old, neu in pairs):
        return data
    neu_data = data
    for old, neu in pairs:
        if neu_data.count(neu) == 1 and neu_data.count(old) == 0:
            continue
        if neu_data.count(old) != 1 or neu_data.count(neu) != 0:
            raise RuntimeError("Stelle")
        vor = neu_data
        neu_data = neu_data.replace(old, neu, 1)
        if neu_data.replace(neu, b"", 1) != vor.replace(old, b"", 1):
            raise RuntimeError("ausserhalb")
    if ZIEL not in neu_data and b'id="borCard"' not in neu_data:
        raise RuntimeError("Marker")
    return neu_data

def zaehle(raw: bytes):
    doc = json.loads(raw.decode("utf-8"))
    def n(level, role, reserve):
        return sum(1 for t in doc["targets"] if t.get("level") == level and t.get("role") == role and bool(t.get("reserve")) is reserve)
    print("Ziele Stufe1 last_mile %d + reserve %d + backbone %d" % (n(1, "last_mile", False), n(1, "last_mile", True), n(1, "backbone_ref", False)))
    print("Ziele Stufe2 last_mile %d + reserve %d + backbone %d" % (n(2, "last_mile", False), n(2, "last_mile", True), n(2, "backbone_ref", False)))
    print("Ziele Stufe3 last_mile %d + reserve %d + backbone %d" % (n(3, "last_mile", False), n(3, "last_mile", True), n(3, "backbone_ref", False)))

def apply_dir(ordner: Path, dry: bool, kein: bool, jetzt=None) -> int:
    paare, neu = load()
    for name in PATCH:
        pfad = ordner / name
        if pfad.is_symlink() or not pfad.is_file():
            print("STOP: %s fehlt" % name)
            return 2
    blobs = {name: (ordner / name).read_bytes() for name in PATCH}
    for name in NEU:
        pfad = ordner / name
        if pfad.exists() and (pfad.is_symlink() or not pfad.is_file()):
            print("STOP: %s kein regulaeres File" % name)
            return 2
        blobs[name] = pfad.read_bytes() if pfad.is_file() else None
    for name in PATCH:
        print("%s basis sha16 %s" % (name, sha(blobs[name])[:16]))
    try:
        ziel = {name: verwandle(blobs[name], paare[name]) for name in PATCH}
        for name in NEU:
            ziel[name] = neu[name]
    except RuntimeError:
        print("STOP: Stelle unbekannt")
        return 2
    for name in list(PATCH) + list(NEU):
        print("%s endstand sha16 %s bytes %d" % (name, sha(ziel[name])[:16], len(ziel[name])))
    zaehle(ziel["blackout_radar_targets.json"])
    if all(blobs[name] == ziel[name] for name in list(PATCH) + list(NEU)):
        print("bereits installiert, keine Aenderung, kein Neustart")
        return 0
    for name in PATCH:
        if ziel[name] == blobs[name]:
            continue
        if not basis_ok(name, blobs[name]):
            print("STOP: %s %s ist nicht die Basis" % (name, sha(blobs[name])[:16]))
            return 2
    for name in NEU:
        if blobs[name] is not None and blobs[name] != ziel[name]:
            print("STOP: %s weicht ab" % name)
            return 2
    if MARKER not in ziel["dashboard.py"] or ZIEL not in ziel["dashboard.py"] or b'id="borCard"' not in ziel["lage_pages.py"]:
        print("STOP: Marker fehlt im Ergebnis")
        return 2
    for name in ("dashboard.py", "lage_pages.py", "blackout_radar.py"):
        try:
            compile(ziel[name], name, "exec")
        except SyntaxError as exc:
            print("STOP: Syntax %s %s" % (name, exc.lineno))
            return 2
    frei, meldung = fenster(jetzt)
    print(meldung)
    if not frei and not dry:
        print("STOP: Neustart-Sperre Minute 45-59 und 00-04 Berlin. Nichts geschrieben.")
        return 2
    if dry:
        print("DRY-RUN: kein Backup, kein Schreiben, kein Neustart")
        return 0
    try:
        for name in list(PATCH) + list(NEU):
            if blobs[name] == ziel[name]:
                continue
            pfad = ordner / name
            if pfad.exists():
                sichern(pfad, blobs[name])
            schreiben(pfad, ziel[name])
    except (OSError, RuntimeError) as exc:
        print("STOP beim Schreiben: %s" % exc)
        return 3
    print("geschrieben. Blackout-Radar Stufe 1-3, kein Push.")
    if kein:
        print("Kein Neustart in dieser Pruefung.")
        return 0
    frei, meldung = fenster()
    print(meldung)
    if not frei:
        print("STOP: Datei ist neu, der Neustart bleibt in der Sperre aus.")
        return 2
    import subprocess
    subprocess.run(["systemctl", "restart", "prepper-dashboard.service"], check=False)
    print("Nur prepper-dashboard neu gestartet.")
    return 0

def selftest() -> int:
    assert fenster(datetime(2026, 11, 13, 12, 12))[0]
    assert not fenster(datetime(2026, 11, 13, 12, 45))[0]
    assert not fenster(datetime(2026, 11, 13, 12, 0))[0] and not fenster(datetime(2026, 11, 13, 12, 4))[0]
    assert basis_ok("dashboard.py", b"_PSH_ARM") is False
    import tempfile
    ordner = Path(tempfile.mkdtemp(prefix="bor-apply-"))
    for name in PATCH:
        (ordner / name).write_bytes(b"UNBERUEHRT")
    vorher = {name: (ordner / name).read_bytes() for name in PATCH}
    assert apply_dir(ordner, False, True, datetime(2026, 11, 13, 12, 12)) == 2
    assert {name: (ordner / name).read_bytes() for name in PATCH} == vorher
    assert not (ordner / "blackout_radar.py").exists()
    print("selftest ok")
    return 0

def main(argv):
    args = argv[1:]
    dry = kein = False
    wurzel = DASH
    i = 0
    while i < len(args):
        a = args[i]
        if a == "--dry-run":
            dry = True
        elif a == "--kein-neustart":
            kein = True
        elif a == "--selftest":
            return selftest()
        elif a == "--wurzel":
            i += 1
            wurzel = Path(args[i])
        else:
            print("STOP: unbekanntes Argument")
            return 2
        i += 1
    return apply_dir(wurzel, dry, kein)

PAYLOAD = {"pairs":{"dashboard.py":[{"old":"IyA9PT09PSAvaGJNZXNoID09PT09CgoKaWYgX19uYW1lX18gPT0gIl9fbWFpbl9fIjoK","new":""}],"lage_pages.py":[{"old":"","new":""}]},"neu":{"blackout_radar.py":"","blackout_radar_targets.json":""}}

if __name__ == "__main__":
    sys.exit(main(sys.argv))
